// Physics integrator and coordinate transforms

import type { Particles, Config } from './types';
import { primaries } from './cr3bp';

/**
 * Compute acceleration on a test particle at (x, y) at time t in inertial frame.
 */
export function accel(
  x: number,
  y: number,
  t: number,
  mu: number,
  eps: number
): { ax: number; ay: number } {
  const { r1x, r1y, r2x, r2y } = primaries(mu, t);

  const dx1 = x - r1x;
  const dy1 = y - r1y;
  const dx2 = x - r2x;
  const dy2 = y - r2y;

  const inv31 = Math.pow(dx1 * dx1 + dy1 * dy1 + eps * eps, -1.5);
  const inv32 = Math.pow(dx2 * dx2 + dy2 * dy2 + eps * eps, -1.5);

  const ax = -(1 - mu) * dx1 * inv31 - mu * dx2 * inv32;
  const ay = -(1 - mu) * dy1 * inv31 - mu * dy2 * inv32;

  return { ax, ay };
}

/**
 * Transform from inertial to rotating frame.
 */
export function toRotating(
  x: number,
  y: number,
  vx: number,
  vy: number,
  t: number
): { xr: number; yr: number; vrotx: number; vroty: number } {
  const c = Math.cos(t);
  const s = Math.sin(t);

  // Rotate position
  const xr = c * x + s * y;
  const yr = -s * x + c * y;

  // Rotate velocity and subtract ω × r with ω=1
  const vrotx = c * vx + s * vy + yr;
  const vroty = -s * vx + c * vy - xr;

  return { xr, yr, vrotx, vroty };
}

/**
 * Transform from rotating to inertial frame.
 */
export function toInertial(
  xr: number,
  yr: number,
  vrotx: number,
  vroty: number,
  t: number
): { x: number; y: number; vx: number; vy: number } {
  const c = Math.cos(t);
  const s = Math.sin(t);

  // Rotate position back
  const x = c * xr - s * yr;
  const y = s * xr + c * yr;

  // Rotate velocity back and add ω × r
  const vx = c * vrotx - s * vroty - y;
  const vy = s * vrotx + c * vroty + x;

  return { x, y, vx, vy };
}

/**
 * Velocity-Verlet (leapfrog) integrator step.
 * Returns new time t + dt.
 */
export function stepLeapfrog(parts: Particles, cfg: Config, t: number): number {
  const { x, y, vx, vy, alive } = parts;
  const N = x.length;
  const dt = cfg.dt;

  // Half kick
  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;
    const a = accel(x[i], y[i], t, cfg.mu, cfg.eps);
    vx[i] += 0.5 * dt * a.ax;
    vy[i] += 0.5 * dt * a.ay;
  }

  // Drift
  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;
    x[i] += dt * vx[i];
    y[i] += dt * vy[i];
  }

  const t1 = t + dt;

  // Optional rotating-frame drag
  if (cfg.drag > 0) {
    const k = Math.exp(-cfg.drag * dt);

    for (let i = 0; i < N; i++) {
      if (!alive[i]) continue;

      // Transform to rotating frame
      const rot = toRotating(x[i], y[i], vx[i], vy[i], t1);

      // Apply drag
      const vrotx2 = k * rot.vrotx;
      const vroty2 = k * rot.vroty;

      // Transform back to inertial
      const iner = toInertial(rot.xr, rot.yr, vrotx2, vroty2, t1);
      vx[i] = iner.vx;
      vy[i] = iner.vy;
    }
  }

  // Half kick at t+dt
  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;
    const a = accel(x[i], y[i], t1, cfg.mu, cfg.eps);
    vx[i] += 0.5 * dt * a.ax;
    vy[i] += 0.5 * dt * a.ay;
  }

  // Check for close encounters with the Sun
  // Remove particles closer than 50% of Sun-Jupiter distance
  const sunCloseThreshold = 0.5;
  const sunFarThreshold = 1.35;
  const { r1x, r1y } = primaries(cfg.mu, t1);

  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;
    const dx = x[i] - r1x;
    const dy = y[i] - r1y;
    const distToSun = Math.sqrt(dx * dx + dy * dy);

    if (distToSun < sunCloseThreshold) {
      alive[i] = 0;  // Mark particle as dead
    }
    if (distToSun > sunFarThreshold) {
      alive[i] = 0;  // Mark particle as dead
    }
  }

  return t1;
}
