// Shared type definitions

export interface Vec2 {
  x: number;
  y: number;
}

export interface Config {
  mu: number;           // mass parameter ≈ 9.54e-4 for Sun–Jupiter
  dt: number;           // time step
  eps: number;          // softening parameter
  drag: number;         // rotating-frame drag coefficient
  maxDist: number;      // escape threshold
  trails: boolean;      // show particle trails
  trailLen: number;     // trail length in steps
}

export interface Particles {
  // Structure of Arrays for performance
  x: Float32Array;
  y: Float32Array;
  vx: Float32Array;
  vy: Float32Array;
  cls: Uint8Array;      // classification code: 0=unknown, 1=L4, 2=L5, 3=horseshoe
  alive: Uint8Array;
  // rolling buffers for classification
  dlamWin: Float32Array; // last W Δλ samples per particle (flattened)
  idxWin: Uint16Array;   // write index per particle
  // trail data
  trails: Float32Array;  // ring buffer of positions [x0,y0,x1,y1,...]
}

export interface SimState {
  t: number;            // current simulation time
  N: number;            // number of particles
  cfg: Config;
  parts: Particles;
  paused: boolean;
  speed: number;        // speed multiplier (model seconds per real second)
}

export interface Camera {
  cx: number;           // world center x
  cy: number;           // world center y
  scale: number;        // pixels per world unit
}

export interface Primaries {
  r1x: number;          // Sun position x
  r1y: number;          // Sun position y
  r2x: number;          // Jupiter position x
  r2y: number;          // Jupiter position y
}

export interface LagrangePoints {
  L1: Vec2;
  L2: Vec2;
  L3: Vec2;
  L4: Vec2;
  L5: Vec2;
}

// Classification codes
export const CLASS_UNKNOWN = 0;
export const CLASS_TADPOLE_L4 = 1;
export const CLASS_TADPOLE_L5 = 2;
export const CLASS_HORSESHOE = 3;
export const CLASS_ESCAPE = 4;
