// Main application entry point

import type { SimState, Camera, LagrangePoints } from './core/types';
import type { UIState } from './ui/controls';
import { createSimState, presetUniformScatter } from './sim/world';
import { Scheduler } from './sim/scheduler';
import { computeLagrangePoints } from './core/cr3bp';
import { primaries } from './core/cr3bp';
import { drawInertialFrame, drawRotatingFrame } from './render/draw2d';
import { computeOmegaGrid } from './render/contours';
import type { ContourGrid } from './render/contours';
import { initControls, updateReadouts } from './ui/controls';
import { createCamera } from './ui/events';

/**
 * Main application class.
 */
class LagrangeApp {
  private state: SimState;
  private scheduler: Scheduler;
  private lpoints: LagrangePoints;
  private omegaGrid: ContourGrid | null = null;

  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;

  private cam: Camera;

  private uiState: UIState = {
    showPotential: false,
    showRotatingFrame: true
  };

  private frameTimeSmooth = 0;

  constructor() {
    // Initialize simulation state
    this.state = createSimState(20000);
    this.lpoints = computeLagrangePoints(this.state.cfg.mu);

    // Get canvas element
    this.canvas = document.getElementById('canvas') as HTMLCanvasElement;
    this.ctx = this.canvas.getContext('2d')!;

    // Initialize camera (fixed, no zoom/pan)
    this.cam = createCamera(150);

    // Precompute potential grid
    this.omegaGrid = computeOmegaGrid(
      this.state.cfg.mu,
      -2, 2,
      -2, 2,
      256, 256
    );

    // Initialize scheduler
    this.scheduler = new Scheduler(this.state);

    // Initialize controls
    initControls(
      () => this.state,
      this.uiState,
      () => this.reset(),
      (count: number) => this.changeParticleCount(count)
    );

    // Start animation loop
    this.animate();
  }

  /**
   * Change particle count and re-scatter.
   */
  private changeParticleCount(count: number): void {
    this.state = createSimState(count);
    this.scheduler = new Scheduler(this.state);
    this.lpoints = computeLagrangePoints(this.state.cfg.mu);
    presetUniformScatter(this.state);
  }

  /**
   * Reset simulation by re-scattering particles.
   */
  private reset(): void {
    this.state.t = 0;
    this.scheduler.reset();
    presetUniformScatter(this.state);
  }

  /**
   * Main animation loop.
   */
  private animate = (): void => {
    const now = performance.now();
    const frameStart = now;

    // Step physics
    this.scheduler.tick(now);

    // Render current frame
    this.render();

    // Update readouts
    const frameTime = performance.now() - frameStart;
    this.frameTimeSmooth = 0.9 * this.frameTimeSmooth + 0.1 * frameTime;
    updateReadouts(this.state, this.frameTimeSmooth);

    requestAnimationFrame(this.animate);
  };

  /**
   * Render current frame (rotating or inertial based on toggle).
   */
  private render(): void {
    const prims = primaries(this.state.cfg.mu, this.state.t);

    if (this.uiState.showRotatingFrame) {
      // Render rotating frame
      drawRotatingFrame(
        this.ctx,
        this.state,
        this.cam,
        this.lpoints,
        this.uiState.showPotential,
        this.omegaGrid
      );

      // Draw frame label
      this.ctx.fillStyle = 'white';
      this.ctx.font = '14px sans-serif';
      this.ctx.fillText('Rotating Frame', 10, 20);
    } else {
      // Render inertial frame
      drawInertialFrame(
        this.ctx,
        this.state,
        this.cam,
        prims
      );

      // Draw frame label
      this.ctx.fillStyle = 'white';
      this.ctx.font = '14px sans-serif';
      this.ctx.fillText('Inertial Frame', 10, 20);
    }
  }
}

// Start application when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  new LagrangeApp();
});
