// Event handling for canvas interaction

import type { Camera } from '../core/types';
import { screenToWorld } from '../render/draw2d';

/**
 * Initialize camera with default view.
 */
export function createCamera(scale: number = 150): Camera {
  return {
    cx: 0,
    cy: 0,
    scale
  };
}

/**
 * Set up mouse/touch events for panning and zooming.
 */
export function initCanvasEvents(
  canvas: HTMLCanvasElement,
  cam: Camera,
  onPaint?: (wx: number, wy: number) => void
): void {
  let isDragging = false;
  let lastX = 0;
  let lastY = 0;

  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    lastX = e.offsetX;
    lastY = e.offsetY;
  });

  canvas.addEventListener('mousemove', (e) => {
    if (isDragging) {
      const dx = e.offsetX - lastX;
      const dy = e.offsetY - lastY;

      cam.cx -= dx / cam.scale;
      cam.cy += dy / cam.scale;  // flip y

      lastX = e.offsetX;
      lastY = e.offsetY;
    }
  });

  canvas.addEventListener('mouseup', () => {
    isDragging = false;
  });

  canvas.addEventListener('mouseleave', () => {
    isDragging = false;
  });

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();

    const zoom = e.deltaY > 0 ? 0.9 : 1.1;
    cam.scale *= zoom;

    // Clamp scale
    cam.scale = Math.max(50, Math.min(cam.scale, 500));
  });

  // Paintbrush mode - click to add particle
  canvas.addEventListener('click', (e) => {
    if (onPaint) {
      const world = screenToWorld(e.offsetX, e.offsetY, cam, canvas.width, canvas.height);
      onPaint(world.wx, world.wy);
    }
  });
}
