// Fixed-step scheduler for deterministic physics

import type { SimState } from '../core/types';
import { stepLeapfrog } from '../core/physics';
import { updateDeltaLambdaBuffers, classify } from '../core/classify';

const CLASSIFY_WINDOW = 200;      // classification window size (steps)
const CLASSIFY_INTERVAL = 10;     // classify every N steps

/**
 * Scheduler that accumulates real time and steps physics at fixed intervals.
 */
export class Scheduler {
  private acc = 0;
  private last = performance.now();
  private stepCount = 0;

  constructor(
    private state: SimState,
    private onStep?: (state: SimState) => void
  ) {}

  /**
   * Advance simulation by real time dt (in milliseconds).
   */
  tick(now: number): void {
    if (this.state.paused) {
      this.last = now;
      return;
    }

    const dtReal = (now - this.last) / 1000;  // convert to seconds
    this.last = now;

    // Accumulate time scaled by speed
    this.acc += dtReal * this.state.speed;

    // Step physics at fixed intervals
    while (this.acc >= this.state.cfg.dt) {
      this.state.t = stepLeapfrog(
        this.state.parts,
        this.state.cfg,
        this.state.t
      );

      // Update classification buffers every step
      updateDeltaLambdaBuffers(this.state, CLASSIFY_WINDOW);

      // Classify particles periodically
      this.stepCount++;
      if (this.stepCount % CLASSIFY_INTERVAL === 0) {
        classify(this.state, CLASSIFY_WINDOW);
      }

      this.acc -= this.state.cfg.dt;

      if (this.onStep) {
        this.onStep(this.state);
      }
    }
  }

  reset(): void {
    this.acc = 0;
    this.last = performance.now();
    this.stepCount = 0;
  }
}
