// Behavioral classification of particle trajectories

import type { SimState } from './types';
import { CLASS_UNKNOWN, CLASS_TADPOLE_L4, CLASS_TADPOLE_L5 } from './types';

/**
 * Update circular buffers of Δλ (angle in rotating frame) for each particle.
 */
export function updateDeltaLambdaBuffers(state: SimState, window: number): void {
  const { x, y, alive, dlamWin, idxWin } = state.parts;
  const N = x.length;
  const t = state.t;
  const c = Math.cos(t);
  const s = Math.sin(t);

  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;

    // Transform to rotating frame
    const xr = c * x[i] + s * y[i];
    const yr = -s * x[i] + c * y[i];

    // Compute angle (Jupiter is at angle 0 in rotating frame)
    let ang = Math.atan2(yr, xr) * 180 / Math.PI;

    // Wrap to [-180, 180]
    if (ang > 180) ang -= 360;
    if (ang < -180) ang += 360;

    // Store in circular buffer
    const base = i * window;
    const j = idxWin[i] % window;
    dlamWin[base + j] = ang;
    idxWin[i] = (j + 1) % window;
  }
}

/**
 * Classify particles based on their libration amplitude and mean angle.
 */
export function classify(state: SimState, window: number): void {
  const { dlamWin, cls, alive } = state.parts;
  const N = cls.length;

  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;

    const base = i * window;
    let minA = 1e9;
    let maxA = -1e9;
    let sum = 0;
    let count = 0;

    // Find min, max, and mean of Δλ over the window
    for (let k = 0; k < window; k++) {
      const v = dlamWin[base + k];
      if (!Number.isFinite(v)) continue;
      minA = Math.min(minA, v);
      maxA = Math.max(maxA, v);
      sum += v;
      count++;
    }

    // Need at least 80% of window filled
    if (count < window * 0.8) continue;

    const amplitude = maxA - minA;
    const mean = sum / count;

    let code = CLASS_UNKNOWN;

    if (amplitude < 180) {
      // Tadpole orbit
      if (mean >= 20 && mean <= 100) {
        code = CLASS_TADPOLE_L4;
      } else if (mean <= -20 && mean >= -100) {
        code = CLASS_TADPOLE_L5;
      }
    }
    // No horseshoe classification

    cls[i] = code;
  }
}
