// Effective potential and zero-velocity curve rendering

import { effectivePotential } from '../core/cr3bp';
import type { Camera, LagrangePoints } from '../core/types';

export interface ContourGrid {
  data: Float32Array;
  nx: number;
  ny: number;
  xmin: number;
  xmax: number;
  ymin: number;
  ymax: number;
}

/**
 * Compute effective potential on a grid.
 */
export function computeOmegaGrid(
  mu: number,
  xmin: number,
  xmax: number,
  ymin: number,
  ymax: number,
  nx: number,
  ny: number
): ContourGrid {
  const data = new Float32Array(nx * ny);
  const dx = (xmax - xmin) / (nx - 1);
  const dy = (ymax - ymin) / (ny - 1);

  for (let j = 0; j < ny; j++) {
    for (let i = 0; i < nx; i++) {
      const x = xmin + i * dx;
      const y = ymin + j * dy;
      const omega = effectivePotential(x, y, mu);
      data[j * nx + i] = omega;
    }
  }

  return { data, nx, ny, xmin, xmax, ymin, ymax };
}

/**
 * Draw zero-velocity curve (contour where 2Ω = C) using marching squares.
 */
export function drawZeroVelocityCurve(
  ctx: CanvasRenderingContext2D,
  grid: ContourGrid,
  C: number,
  cam: Camera
): void {
  const isoValue = C / 2;  // 2Ω = C => Ω = C/2
  const { data, nx, ny, xmin, xmax, ymin, ymax } = grid;

  const dx = (xmax - xmin) / (nx - 1);
  const dy = (ymax - ymin) / (ny - 1);

  ctx.strokeStyle = '#00c6ff';
  ctx.lineWidth = 1.5;
  ctx.globalAlpha = 0.5;

  // Simple marching squares
  for (let j = 0; j < ny - 1; j++) {
    for (let i = 0; i < nx - 1; i++) {
      const x = xmin + i * dx;
      const y = ymin + j * dy;

      const v00 = data[j * nx + i];
      const v10 = data[j * nx + (i + 1)];
      const v01 = data[(j + 1) * nx + i];
      const v11 = data[(j + 1) * nx + (i + 1)];

      // Compute case
      let caseId = 0;
      if (v00 >= isoValue) caseId |= 1;
      if (v10 >= isoValue) caseId |= 2;
      if (v11 >= isoValue) caseId |= 4;
      if (v01 >= isoValue) caseId |= 8;

      if (caseId === 0 || caseId === 15) continue;

      // Interpolate edge crossings
      const interp = (v0: number, v1: number, t: number) => {
        return t + (isoValue - v0) / (v1 - v0);
      };

      const pts: Array<{ x: number; y: number }> = [];

      // Bottom edge
      if ((caseId & 3) === 1 || (caseId & 3) === 2) {
        const t = interp(v00, v10, 0);
        pts.push({ x: x + t * dx, y });
      }

      // Right edge
      if ((caseId & 6) === 2 || (caseId & 6) === 4) {
        const t = interp(v10, v11, 0);
        pts.push({ x: x + dx, y: y + t * dy });
      }

      // Top edge
      if ((caseId & 12) === 4 || (caseId & 12) === 8) {
        const t = interp(v01, v11, 0);
        pts.push({ x: x + t * dx, y: y + dy });
      }

      // Left edge
      if ((caseId & 9) === 1 || (caseId & 9) === 8) {
        const t = interp(v00, v01, 0);
        pts.push({ x, y: y + t * dy });
      }

      // Draw line segments
      if (pts.length >= 2) {
        ctx.beginPath();
        const cx = ctx.canvas.width / 2;
        const cy = ctx.canvas.height / 2;
        const sx0 = cx + (pts[0].x - cam.cx) * cam.scale;
        const sy0 = cy - (pts[0].y - cam.cy) * cam.scale;
        ctx.moveTo(sx0, sy0);
        for (let k = 1; k < pts.length; k++) {
          const sx = cx + (pts[k].x - cam.cx) * cam.scale;
          const sy = cy - (pts[k].y - cam.cy) * cam.scale;
          ctx.lineTo(sx, sy);
        }
        ctx.stroke();
      }
    }
  }

  ctx.globalAlpha = 1.0;
}

/**
 * Draw effective potential as a colored heat map.
 * Focuses color scale on Lagrange point region for better visualization.
 * Uses logarithmic scaling and inferno palette (L4/L5 = bright, far = black).
 */
export function drawPotentialGrid(
  ctx: CanvasRenderingContext2D,
  grid: ContourGrid,
  cam: Camera,
  lpoints: LagrangePoints,
  mu: number
): void {
  const { data, nx, ny, xmin, xmax, ymin, ymax } = grid;

  // Compute potential at Lagrange points to understand the range
  const omegaL4 = effectivePotential(lpoints.L4.x, lpoints.L4.y, mu);
  const omegaL1 = effectivePotential(lpoints.L1.x, lpoints.L1.y, mu);

  // In the effective potential, L4/L5 are at LOWER potential (stable equilibria)
  // Regions far away or close to primaries have HIGHER potential
  // So: L4 < L1 < far regions

  // Set color range: vmin (L4/L5, low) should map to bright yellow
  //                   vmax (far/close, high) should map to black
  const vmin = omegaL4; // Start just below L4
  const vmax = omegaL1 + 0.8; // Extend above L1 to catch far regions

  const dx = (xmax - xmin) / (nx - 1);
  const dy = (ymax - ymin) / (ny - 1);

  ctx.globalAlpha = 0.5;

  for (let j = 0; j < ny - 1; j++) {
    for (let i = 0; i < nx - 1; i++) {
      const x = xmin + i * dx;
      const y = ymin + j * dy;

      let v = data[j * nx + i];
      if (!isFinite(v)) continue;

      // Clamp to our range
      v = Math.max(vmin, Math.min(v, vmax));

      // Normalize to [0, 1] where 0 = low potential (L4), 1 = high potential (far)
      const tLinear = (v - vmin) / (vmax - vmin);

      // Apply logarithmic scaling
      const k = 400;
      const tLog = Math.log(1 + tLinear * k) / Math.log(1 + k);

      // NOW: tLog = 0 means low potential (L4/L5)
      //      tLog = 1 means high potential (far/close to primaries)
      // We want: low potential → bright yellow, high potential → black
      // So we INVERT: t = 1 - tLog
      const t = 1 - tLog;

      // Inferno palette: t=1 (low pot, L4/L5) = bright, t=0 (high pot, far) = black
      let r: number, g: number, b: number;

      if (t < 0.25) {
        // Black to dark purple (very high potential - far regions)
        const tt = t / 0.25;
        r = Math.floor(40 * tt);
        g = 0;
        b = Math.floor(60 * tt);
      } else if (t < 0.5) {
        // Dark purple to red (high potential - between L1 and far)
        const tt = (t - 0.25) / 0.25;
        r = Math.floor(40 + 180 * tt);
        g = Math.floor(20 * tt);
        b = Math.floor(60 * (1 - tt));
      } else if (t < 0.75) {
        // Red to orange (medium - around L1/L2/L3)
        const tt = (t - 0.5) / 0.25;
        r = 220;
        g = Math.floor(20 + 150 * tt);
        b = 0;
      } else {
        // Orange to bright yellow (low potential - L4/L5)
        const tt = (t - 0.75) / 0.25;
        r = Math.floor(220 + 35 * tt);
        g = Math.floor(170 + 85 * tt);
        b = Math.floor(200 * tt);
      }

      ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;

      // Convert to screen coords
      const cx = ctx.canvas.width / 2;
      const cy = ctx.canvas.height / 2;
      const sx = cx + (x - cam.cx) * cam.scale;
      const sy = cy - (y - cam.cy) * cam.scale;
      const sw = dx * cam.scale;
      const sh = dy * cam.scale;

      ctx.fillRect(sx, sy - sh, sw, sh);
    }
  }

  ctx.globalAlpha = 1.0;
}
