// Canvas 2D rendering

import type { SimState, Camera, LagrangePoints, Primaries } from '../core/types';
import { toRotating } from '../core/physics';
import { CLASS_TADPOLE_L4, CLASS_TADPOLE_L5 } from '../core/types';
import type { ContourGrid } from './contours';
import { drawPotentialGrid } from './contours';

/**
 * Get color for particle based on classification.
 */
function getParticleColor(cls: number): string {
  switch (cls) {
    case CLASS_TADPOLE_L4: return '#22c55e';  // green
    case CLASS_TADPOLE_L5: return '#f59e0b';  // orange
    default: return '#64b5f6';                // blue
  }
}

/**
 * World to screen coordinates.
 */
function worldToScreen(
  wx: number,
  wy: number,
  cam: Camera
): { sx: number; sy: number } {
  const sx = (wx - cam.cx) * cam.scale + cam.scale * 2;
  const sy = -(wy - cam.cy) * cam.scale + cam.scale * 2;  // flip y
  return { sx, sy };
}

/**
 * Screen to world coordinates.
 */
export function screenToWorld(
  sx: number,
  sy: number,
  cam: Camera,
  canvasWidth: number,
  canvasHeight: number
): { wx: number; wy: number } {
  const cx = canvasWidth / 2;
  const cy = canvasHeight / 2;
  const wx = cam.cx + (sx - cx) / cam.scale;
  const wy = cam.cy - (sy - cy) / cam.scale;
  return { wx, wy };
}

/**
 * Draw particles in inertial frame.
 */
export function drawInertialFrame(
  ctx: CanvasRenderingContext2D,
  state: SimState,
  cam: Camera,
  prims: Primaries
): void {
  const { x, y, alive, cls } = state.parts;
  const N = x.length;

  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

  // Draw primaries
  const sun = worldToScreen(prims.r1x, prims.r1y, cam);
  const jup = worldToScreen(prims.r2x, prims.r2y, cam);

  ctx.fillStyle = '#fbbf24';  // yellow
  ctx.beginPath();
  ctx.arc(sun.sx, sun.sy, 8, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = '#f97316';  // orange
  ctx.beginPath();
  ctx.arc(jup.sx, jup.sy, 6, 0, 2 * Math.PI);
  ctx.fill();

  // Draw particles
  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;

    const p = worldToScreen(x[i], y[i], cam);
    ctx.fillStyle = getParticleColor(cls[i]);
    ctx.fillRect(p.sx - 1.5, p.sy - 1.5, 3, 3);
  }
}

/**
 * Draw particles in rotating frame.
 */
export function drawRotatingFrame(
  ctx: CanvasRenderingContext2D,
  state: SimState,
  cam: Camera,
  lpoints: LagrangePoints,
  showPotential: boolean,
  omegaGrid: ContourGrid | null
): void {
  const { x, y, alive, cls } = state.parts;
  const N = x.length;
  const t = state.t;

  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

  // Draw effective potential if enabled
  if (showPotential && omegaGrid) {
    drawPotentialGrid(ctx, omegaGrid, cam, lpoints, state.cfg.mu);
  }

  // Draw primaries (fixed in rotating frame)
  const mu = state.cfg.mu;
  const sun = worldToScreen(-mu, 0, cam);
  const jup = worldToScreen(1 - mu, 0, cam);

  ctx.fillStyle = '#fbbf24';  // yellow
  ctx.beginPath();
  ctx.arc(sun.sx, sun.sy, 8, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = '#f97316';  // orange
  ctx.beginPath();
  ctx.arc(jup.sx, jup.sy, 6, 0, 2 * Math.PI);
  ctx.fill();

  // Draw Lagrange points
  const drawLPoint = (lp: { x: number; y: number }, label: string) => {
    const p = worldToScreen(lp.x, lp.y, cam);
    ctx.strokeStyle = '#00c6ff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(p.sx, p.sy, 4, 0, 2 * Math.PI);
    ctx.stroke();

    ctx.fillStyle = '#00c6ff';
    ctx.font = '11px Inter, sans-serif';
    ctx.fillText(label, p.sx + 8, p.sy - 8);
  };

  drawLPoint(lpoints.L1, 'L1');
  drawLPoint(lpoints.L2, 'L2');
  drawLPoint(lpoints.L3, 'L3');
  drawLPoint(lpoints.L4, 'L4');
  drawLPoint(lpoints.L5, 'L5');

  // Draw particles in rotating frame
  for (let i = 0; i < N; i++) {
    if (!alive[i]) continue;

    const rot = toRotating(x[i], y[i], 0, 0, t);
    const p = worldToScreen(rot.xr, rot.yr, cam);

    ctx.fillStyle = getParticleColor(cls[i]);
    ctx.fillRect(p.sx - 1.5, p.sy - 1.5, 3, 3);
  }
}
