// Simulation world state and particle management

import type { SimState, Particles, Config } from '../core/types';
import { mulberry32, randn } from '../core/rng';
import { toInertial } from '../core/physics';
import { computeLagrangePoints } from '../core/cr3bp';

/**
 * Create a new simulation state with the given number of particles.
 */
export function createSimState(N: number): SimState {
  const cfg: Config = {
    mu: 9.54e-3,        // 10x Sun-Jupiter system
    dt: 0.005,          // time step
    eps: 1e-4,          // softening
    drag: 0.0,          // no drag by default
    maxDist: 5.0,       // escape threshold
    trails: false,
    trailLen: 100
  };

  const parts: Particles = {
    x: new Float32Array(N),
    y: new Float32Array(N),
    vx: new Float32Array(N),
    vy: new Float32Array(N),
    cls: new Uint8Array(N),
    alive: new Uint8Array(N),
    dlamWin: new Float32Array(N * 200),  // window of 200 steps
    idxWin: new Uint16Array(N),
    trails: new Float32Array(N * cfg.trailLen * 2)
  };

  return {
    t: 0,
    N,
    cfg,
    parts,
    paused: false,
    speed: 1.0
  };
}

/**
 * Reset all particles to inactive state.
 */
export function clearParticles(state: SimState): void {
  state.parts.alive.fill(0);
  state.parts.cls.fill(0);
  state.parts.dlamWin.fill(NaN);
  state.parts.idxWin.fill(0);
  state.t = 0;
}

/**
 * Seed particles in a Gaussian cloud around a point in rotating frame.
 */
export function seedCloud(
  state: SimState,
  xr: number,
  yr: number,
  N: number,
  sigmaPos: number,
  sigmaVel: number,
  seed: number
): void {
  const rng = mulberry32(seed);
  const { x, y, vx, vy, alive } = state.parts;
  const t = state.t;

  for (let i = 0; i < N; i++) {
    // Generate position in rotating frame
    const dxr = sigmaPos * randn(rng);
    const dyr = sigmaPos * randn(rng);
    const xri = xr + dxr;
    const yri = yr + dyr;

    // Generate velocity in rotating frame
    const vrotxi = sigmaVel * randn(rng);
    const vrotyi = sigmaVel * randn(rng);

    // Transform to inertial frame
    const iner = toInertial(xri, yri, vrotxi, vrotyi, t);

    x[i] = iner.x;
    y[i] = iner.y;
    vx[i] = iner.vx;
    vy[i] = iner.vy;
    alive[i] = 1;
  }
}

/**
 * Add a single particle at a point in rotating frame with v_rot = 0.
 */
export function addCoRotParticle(
  state: SimState,
  xr: number,
  yr: number,
  index: number
): void {
  const t = state.t;
  const { x, y, vx, vy, alive } = state.parts;

  // v_rot = 0 => inertial v = ω × r
  const iner = toInertial(xr, yr, 0, 0, t);

  x[index] = iner.x;
  y[index] = iner.y;
  vx[index] = iner.vx;
  vy[index] = iner.vy;
  alive[index] = 1;
}

/**
 * Preset: Trojan cloud at L4.
 */
export function presetTrojanL4(state: SimState): void {
  clearParticles(state);
  const lpoints = computeLagrangePoints(state.cfg.mu);
  seedCloud(state, lpoints.L4.x, lpoints.L4.y, state.N, 0.02, 0.005, 12345);
}

/**
 * Preset: Trojan cloud at L5.
 */
export function presetTrojanL5(state: SimState): void {
  clearParticles(state);
  const lpoints = computeLagrangePoints(state.cfg.mu);
  seedCloud(state, lpoints.L5.x, lpoints.L5.y, state.N, 0.02, 0.005, 54321);
}

/**
 * Preset: Horseshoe orbits.
 */
export function presetHorseshoe(state: SimState): void {
  clearParticles(state);
  // Seed around x ≈ 0.9 in rotating frame
  seedCloud(state, 0.9, 0, state.N, 0.1, 0.01, 99999);
}

/**
 * Preset: Uniform scatter across space with co-rotating velocities.
 */
export function presetUniformScatter(state: SimState): void {
  clearParticles(state);
  const rng = mulberry32(77777);
  const { x, y, vx, vy, alive } = state.parts;
  const t = state.t;

  // Scatter uniformly in a circular region in rotating frame
  const maxRadius = 1.5;  // Extend beyond the primaries

  // Distance thresholds (same as in physics.ts)
  const sunCloseThreshold = 0.5;
  const sunFarThreshold = 1.35;

  // Get Sun position at time t
  const c = Math.cos(t);
  const s = Math.sin(t);
  const r1x = -state.cfg.mu * c;
  const r1y = -state.cfg.mu * s;

  for (let i = 0; i < state.N; i++) {
    // Uniform distribution in circle using rejection sampling
    let xri: number, yri: number, r2: number;
    do {
      xri = (2 * rng() - 1) * maxRadius;
      yri = (2 * rng() - 1) * maxRadius;
      r2 = xri * xri + yri * yri;
    } while (r2 > maxRadius * maxRadius);

    // Start with co-rotating velocity (v_rot = 0)
    // This means they start in equilibrium with the rotating frame
    const iner = toInertial(xri, yri, 0, 0, t);

    x[i] = iner.x;
    y[i] = iner.y;
    vx[i] = iner.vx;
    vy[i] = iner.vy;

    // Check distance to Sun
    const dx = x[i] - r1x;
    const dy = y[i] - r1y;
    const distToSun = Math.sqrt(dx * dx + dy * dy);

    // Mark particle as alive only if it's within the acceptable range
    if (distToSun >= sunCloseThreshold && distToSun <= sunFarThreshold) {
      alive[i] = 1;
    } else {
      alive[i] = 0;
    }
  }
}
