// CR3BP (Circular Restricted Three-Body Problem) calculations

import type { Primaries, LagrangePoints } from './types';

/**
 * Compute positions of the two primaries (Sun and Jupiter) at time t
 * in the inertial frame, with barycenter at origin.
 */
export function primaries(mu: number, t: number): Primaries {
  const c = Math.cos(t);
  const s = Math.sin(t);
  // Sun at -μ * [cos t, sin t]
  const r1x = -mu * c;
  const r1y = -mu * s;
  // Jupiter at (1-μ) * [cos t, sin t]
  const r2x = (1 - mu) * c;
  const r2y = (1 - mu) * s;
  return { r1x, r1y, r2x, r2y };
}

/**
 * Solve for collinear Lagrange points L1, L2, L3 using Newton iteration.
 */
export function solveCollinear(mu: number, which: 1 | 2 | 3, iters = 20): number {
  // Initial guesses
  let x = which === 1 ? 1 - mu - Math.cbrt(mu / 3)
        : which === 2 ? 1 - mu + Math.cbrt(mu / 3)
        : -1 - (5 / 12) * mu;

  for (let k = 0; k < iters; k++) {
    const xm = x + mu;
    const xp = x - 1 + mu;
    const r1 = Math.abs(xm);
    const r2 = Math.abs(xp);
    const r13 = r1 * r1 * r1;
    const r23 = r2 * r2 * r2;
    const r15 = r13 * r1 * r1;
    const r25 = r23 * r2 * r2;

    const f = x - (1 - mu) * xm / r13 - mu * xp / r23;
    const df = 1 - (1 - mu) * (1 / r13 - 3 * xm * xm / r15)
                 - mu * (1 / r23 - 3 * xp * xp / r25);
    x -= f / df;
  }
  return x;
}

/**
 * Compute all five Lagrange points for given mass parameter μ.
 */
export function computeLagrangePoints(mu: number): LagrangePoints {
  const L1x = solveCollinear(mu, 1);
  const L2x = solveCollinear(mu, 2);
  const L3x = solveCollinear(mu, 3);

  // L4 and L5 form equilateral triangles with the primaries
  const L4x = 0.5 - mu;
  const L4y = Math.sqrt(3) / 2;
  const L5x = 0.5 - mu;
  const L5y = -Math.sqrt(3) / 2;

  return {
    L1: { x: L1x, y: 0 },
    L2: { x: L2x, y: 0 },
    L3: { x: L3x, y: 0 },
    L4: { x: L4x, y: L4y },
    L5: { x: L5x, y: L5y }
  };
}

/**
 * Compute effective potential Ω in rotating frame.
 */
export function effectivePotential(x: number, y: number, mu: number): number {
  const r1 = Math.sqrt((x + mu) ** 2 + y ** 2);
  const r2 = Math.sqrt((x - 1 + mu) ** 2 + y ** 2);
  return (1 - mu) / r1 + mu / r2 + 0.5 * (x * x + y * y);
}

/**
 * Compute Jacobi constant C for a particle in rotating frame.
 */
export function jacobiConstant(
  x: number, y: number,
  vx: number, vy: number,
  mu: number
): number {
  const omega = effectivePotential(x, y, mu);
  const vSq = vx * vx + vy * vy;
  return 2 * omega - vSq;
}
