// UI controls and state bindings

import type { SimState } from '../core/types';
import { presetUniformScatter } from '../sim/world';

export interface UIState {
  showPotential: boolean;
  showRotatingFrame: boolean;
}

/**
 * Initialize UI controls and bind to simulation state.
 */
export function initControls(
  getState: () => SimState,
  uiState: UIState,
  onReset: () => void,
  onParticleCountChange: (count: number) => void
): void {
  // Particle count slider
  const particleCountSlider = document.getElementById('particleCount') as HTMLInputElement;
  const particleCountValue = document.getElementById('particleCountValue') as HTMLSpanElement;

  particleCountSlider.addEventListener('input', () => {
    const count = parseInt(particleCountSlider.value);
    particleCountValue.textContent = count.toString();
    onParticleCountChange(count);
  });

  // Speed control
  const speedSlider = document.getElementById('speed') as HTMLInputElement;
  const speedValue = document.getElementById('speedValue') as HTMLSpanElement;

  speedSlider.addEventListener('input', () => {
    const state = getState();
    state.speed = parseFloat(speedSlider.value);
    speedValue.textContent = state.speed.toFixed(1) + '×';
  });

  // Display toggles
  const showPotential = document.getElementById('showPotential') as HTMLInputElement;

  showPotential.addEventListener('change', () => {
    uiState.showPotential = showPotential.checked;
  });

  // Frame toggle button
  const toggleFrameBtn = document.getElementById('toggleFrame') as HTMLButtonElement;

  toggleFrameBtn.addEventListener('click', () => {
    uiState.showRotatingFrame = !uiState.showRotatingFrame;
    toggleFrameBtn.textContent = uiState.showRotatingFrame
      ? 'Switch to Inertial Frame'
      : 'Switch to Rotating Frame';
  });

  // Play/Pause
  const playPauseBtn = document.getElementById('playPause') as HTMLButtonElement;

  playPauseBtn.addEventListener('click', () => {
    const state = getState();
    state.paused = !state.paused;
    playPauseBtn.textContent = state.paused ? 'Play' : 'Pause';
  });

  // Reset
  const resetBtn = document.getElementById('reset') as HTMLButtonElement;
  resetBtn.addEventListener('click', onReset);

  // Initialize with scatter preset
  presetUniformScatter(getState());
}

/**
 * Update readout displays.
 */
export function updateReadouts(state: SimState, frameTime: number): void {
  const timeValue = document.getElementById('timeValue') as HTMLSpanElement;
  const particlesValue = document.getElementById('particlesValue') as HTMLSpanElement;
  const frameTimeValue = document.getElementById('frameTimeValue') as HTMLSpanElement;

  timeValue.textContent = state.t.toFixed(2);

  // Count alive particles
  let count = 0;
  for (let i = 0; i < state.N; i++) {
    if (state.parts.alive[i]) count++;
  }
  particlesValue.textContent = count.toString();

  frameTimeValue.textContent = frameTime.toFixed(1) + ' ms';
}
